			}
		case "typescript":
			if strings.HasPrefix(line, "interface ") || strings.HasPrefix(line, "class ") || strings.HasPrefix(line, "type ") {
				parts := strings.Fields(line)
				if len(parts) >= 2 {
					name = strings.TrimSuffix(parts[1], "{")
				}
			}
		}
		if name != "" && len(name) > 2 && len(name) < 40 {
			result = append(result, name)
		}
	}
	return result
}

func extractFunctions(content, lang string) []string {
	var result []string
	lines := strings.Split(content, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		var name string
		switch lang {
		case "rust":
			if strings.HasPrefix(line, "pub fn ") || strings.HasPrefix(line, "fn ") {
				parts := strings.Fields(line)
				if len(parts) >= 2 {
					fn := parts[1]
					if idx := strings.Index(fn, "("); idx > 0 {
						name = fn[:idx]
					}
				}
			}
		case "go":
			if strings.HasPrefix(line, "func ") {
				parts := strings.Fields(line)
				if len(parts) >= 2 {
					fn := parts[1]
					if idx := strings.Index(fn, "("); idx > 0 {
						name = fn[:idx]
					}
				}
			}
		}
		if name != "" && len(name) > 2 && len(name) < 40 {
			result = append(result, name)
		}
	}
	return result
}

func saveQA(pairs []QAPair, path string) {
	f, err := os.Create(path)
	if err != nil {
		fmt.Printf("❌ 저장 실패: %v\n", err)
		return
	}
	defer f.Close()

	enc := json.NewEncoder(f)
	for _, p := range pairs {
		enc.Encode(p)
	}
}

func main() {
	generateQA()
}

