package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// ==================================================
// Phase B: 문자 단위 토크나이저
// ==================================================

type Tokenizer struct {
	charToID map[rune]int
	idToChar map[int]rune
	vocabMap map[string]int // 디버깅용
	size     int
}

// 토크나이저 생성 (한글, ASCII, 특수문자 포함)
func NewTokenizer() *Tokenizer {
	tk := &Tokenizer{
		charToID: make(map[rune]int),
		idToChar: make(map[int]rune),
		vocabMap: make(map[string]int),
	}

	currentID := 0

	// 특수 토큰 (ID: 0-4)
	specialTokens := map[rune]int{
		'<': 0, // <pad>
		'>': 1, // </pad>
		'[': 2, // <unk>
		']': 3, // </unk>
		'^': 4, // <eos>
	}

	for ch, id := range specialTokens {
		tk.charToID[ch] = id
		tk.idToChar[id] = ch
		currentID = id + 1
	}

	// ASCII 문자 (ID: 5-134)
	for i := 32; i <= 126; i++ { // 공백부터 ~까지
		if _, isSpecial := specialTokens[rune(i)]; !isSpecial {
			tk.charToID[rune(i)] = currentID
			tk.idToChar[currentID] = rune(i)
			currentID++
		}
	}

	// 줄바꿈/탭 (ID: 130-131)
	tk.charToID['\n'] = currentID
	tk.idToChar[currentID] = '\n'
	currentID++

	tk.charToID['\t'] = currentID
	tk.idToChar[currentID] = '\t'
	currentID++

	// 한글 음절 (AC00-D7A3: 11172개)
	for i := 0xAC00; i <= 0xD7A3; i++ {
		ch := rune(i)
		tk.charToID[ch] = currentID
		tk.idToChar[currentID] = ch
		currentID++
	}

	// 기타 유니코드 (필요하면 동적 추가)
	tk.size = currentID

	return tk
}

// 문자 → ID
func (tk *Tokenizer) Encode(text string) []int {
	var ids []int
	for _, ch := range text {
		if id, ok := tk.charToID[ch]; ok {
			ids = append(ids, id)
		} else {
			// 미지 문자 → <unk> (ID: 3)
			ids = append(ids, 3)
		}
	}
	return ids
}

// ID → 문자
func (tk *Tokenizer) Decode(ids []int) string {
	var chars []rune
	for _, id := range ids {
		if ch, ok := tk.idToChar[id]; ok {
			chars = append(chars, ch)
		}
	}
	return string(chars)
}

// Vocab 통계
func (tk *Tokenizer) Stats() map[string]interface{} {
	return map[string]interface{}{
		"vocab_size":      tk.size,
		"ascii_chars":     95,
		"korean_chars":    11172,
		"special_tokens":  5,
		"newline_tab":     2,
	}
}

// ==================================================
// 파일 저장
// ==================================================

type VocabJSON struct {
	VocabSize int              `json:"vocab_size"`
	CharToID  map[string]int   `json:"char_to_id"`
	IDToChar  map[string]string `json:"id_to_char"`
	Stats     map[string]interface{} `json:"stats"`
}

func (tk *Tokenizer) SaveVocab(filename string) error {
	// char_to_id 맵 변환 (JSON은 문자열 키만 지원)
	charToIDStr := make(map[string]int)
	for ch, id := range tk.charToID {
		charToIDStr[fmt.Sprintf("%d", ch)] = id
	}

	// id_to_char 맵 변환
	idToCharStr := make(map[string]string)
	for id, ch := range tk.idToChar {
		idToCharStr[fmt.Sprintf("%d", id)] = string(ch)
	}

	vocab := VocabJSON{
		VocabSize: tk.size,
		CharToID:  charToIDStr,
		IDToChar:  idToCharStr,
		Stats:     tk.Stats(),
	}

	data, err := json.MarshalIndent(vocab, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(filename, data, 0644)
}

// ==================================================
// 검증
// ==================================================

func (tk *Tokenizer) Validate(testText string) {
	fmt.Println("\n[Validation Test]")
	fmt.Printf("Original:  %s\n", testText)

	encoded := tk.Encode(testText)
	fmt.Printf("Encoded:   %v\n", encoded[:min(len(encoded), 20)]) // 처음 20개만

	decoded := tk.Decode(encoded)
	fmt.Printf("Decoded:   %s\n", decoded)

	if testText == decoded {
		fmt.Println("✅ Encode/Decode: PASS")
	} else {
		fmt.Println("❌ Encode/Decode: FAIL")
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// ==================================================
// MAIN
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase B: Tokenization                  ║")
	fmt.Println("║  Character-level Tokenizer                             ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// 토크나이저 생성
	fmt.Println("\n[1/4] Creating tokenizer...")
	tk := NewTokenizer()
	fmt.Printf("✅ Vocab size: %d\n", tk.size)

	// 코퍼스 로드
	fmt.Println("\n[2/4] Loading corpus...")
	file, err := os.Open("data/corpus.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var totalLines int
	var sampleText string

	for scanner.Scan() {
		text := scanner.Text()
		if totalLines == 10 && sampleText == "" {
			sampleText = text // 샘플로 10번째 줄 사용
		}
		totalLines++
	}

	fmt.Printf("✅ Corpus lines: %d\n", totalLines)

	// Vocab 저장
	fmt.Println("\n[3/4] Saving vocabulary...")
	if err := tk.SaveVocab("data/vocab.json"); err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("✅ Saved: data/vocab.json")

	// 검증
	fmt.Println("\n[4/4] Validation...")
	tk.Validate("FreeLang 신경망 학습")
	tk.Validate(sampleText)

	// 통계
	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("📊 TOKENIZER SUMMARY")
	fmt.Println(strings.Repeat("═", 60))
	stats := tk.Stats()
	for key, val := range stats {
		fmt.Printf("%-20s: %v\n", key, val)
	}

	fmt.Println("\n✅ Phase B Complete!")
	fmt.Println("\nNext: go run data/dataset.go")
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// ==================================================
// Phase C: 데이터셋 생성 (시퀀스 쌍)
// ==================================================

const (
	SeqLen     = 128  // 시퀀스 길이
	ContextLen = 127  // 입력 길이 (타겟은 +1)
	TrainRatio = 0.9
)

type Dataset struct {
	sequences [][]int
	targets   []int
	vocabSize int
}

// 토크나이저 로드
func LoadTokenizerVocab(filename string) (map[string]int, map[string]string, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, nil, err
	}

	var vocab struct {
		VocabSize int             `json:"vocab_size"`
		CharToID  map[string]int  `json:"char_to_id"`
		IDToChar  map[string]string `json:"id_to_char"`
	}

	if err := json.Unmarshal(data, &vocab); err != nil {
		return nil, nil, err
	}

	return vocab.CharToID, vocab.IDToChar, nil
}

// 토크나이저 (간단한 버전)
type SimpleTokenizer struct {
	charToID map[rune]int
}

func NewSimpleTokenizer(charToIDStr map[string]int) *SimpleTokenizer {
	tk := &SimpleTokenizer{
		charToID: make(map[rune]int),
	}

	// 문자열 키를 rune으로 변환
	for key, id := range charToIDStr {
		var ch rune
		fmt.Sscanf(key, "%d", &ch)
		tk.charToID[ch] = id
	}

	return tk
}

func (tk *SimpleTokenizer) Encode(text string) []int {
	var ids []int
	for _, ch := range text {
		if id, ok := tk.charToID[ch]; ok {
			ids = append(ids, id)
		} else {
			ids = append(ids, 3) // <unk>
		}
	}
	return ids
}

// 데이터셋 생성
func (ds *Dataset) Create(tokenIds []int) {
	// 슬라이딩 윈도우로 시퀀스 쌍 생성
	for i := 0; i+SeqLen < len(tokenIds); i++ {
		seq := tokenIds[i : i+ContextLen]
		target := tokenIds[i+ContextLen]
		ds.sequences = append(ds.sequences, seq)
		ds.targets = append(ds.targets, target)
	}
}

// 학습/검증 분할
func (ds *Dataset) Split() (trainSeqs [][]int, trainTargets []int,
	valSeqs [][]int, valTargets []int) {

	splitIdx := int(float64(len(ds.sequences)) * TrainRatio)

	trainSeqs = ds.sequences[:splitIdx]
	trainTargets = ds.targets[:splitIdx]
	valSeqs = ds.sequences[splitIdx:]
	valTargets = ds.targets[splitIdx:]

	return
}

// 배치 저장 (텍스트 형식 - 더 빠름)
func saveBatch(filename string, seqs [][]int, targets []int) error {
	file, err := os.Create(filename)
	if err != nil {
		return err
	}
	defer file.Close()

	writer := bufio.NewWriter(file)
	defer writer.Flush()

	// 헤더
	fmt.Fprintf(writer, "%d\n", len(seqs))

	// 각 샘플
	for i, seq := range seqs {
		// 시퀀스 (공백 구분)
		for _, id := range seq {
			fmt.Fprintf(writer, "%d ", id)
		}
		// 탭으로 구분 후 타겟
		fmt.Fprintf(writer, "\t%d\n", targets[i])

		// 진행 상황
		if (i+1)%1000000 == 0 {
			fmt.Printf("  Saved %d samples...\n", i+1)
		}
	}

	return nil
}

// ==================================================
// MAIN
// ==================================================

func main() {
	fmt.Println("╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Phase C: Dataset Generation            ║")
	fmt.Println("║  Sliding Window Sequences                              ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝")

	// 토크나이저 로드
	fmt.Println("\n[1/5] Loading tokenizer...")
	charToIDStr, _, err := LoadTokenizerVocab("data/vocab.json")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}
	tk := NewSimpleTokenizer(charToIDStr)
	fmt.Println("✅ Tokenizer loaded")

	// 코퍼스 로드 & 토큰화
	fmt.Println("\n[2/5] Loading corpus...")
	file, err := os.Open("data/corpus.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	var allTokens []int
	scanner := bufio.NewScanner(file)
	lineCount := 0

	for scanner.Scan() {
		text := scanner.Text()
		tokens := tk.Encode(text)
		allTokens = append(allTokens, tokens...)

		// 각 문단 구분 (개행 토큰 추가)
		allTokens = append(allTokens, 44) // '\n'

		lineCount++
		if lineCount%100000 == 0 {
			fmt.Printf("  Processed %d lines (%.0fM tokens)...\n",
				lineCount, float64(len(allTokens))/1e6)
		}
	}

	fmt.Printf("✅ Total tokens: %d (%.1f M)\n", len(allTokens), float64(len(allTokens))/1e6)

	// 데이터셋 생성
	fmt.Println("\n[3/5] Creating dataset...")
	ds := &Dataset{vocabSize: 11267}
	ds.Create(allTokens)
	fmt.Printf("✅ Generated %d sequences\n", len(ds.sequences))

	// 학습/검증 분할
	fmt.Println("\n[4/5] Splitting train/val...")
	trainSeqs, trainTargets, valSeqs, valTargets := ds.Split()
	fmt.Printf("✅ Train: %d samples (90%%)\n", len(trainSeqs))
	fmt.Printf("✅ Val:   %d samples (10%%)\n", len(valSeqs))

	// 저장
	fmt.Println("\n[5/5] Saving datasets...")
	if err := saveBatch("data/train.bin", trainSeqs, trainTargets); err != nil {
		fmt.Printf("❌ Error saving train: %v\n", err)
		os.Exit(1)
	}
	if err := saveBatch("data/val.bin", valSeqs, valTargets); err != nil {
		fmt.Printf("❌ Error saving val: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("✅ Saved: data/train.bin, data/val.bin")

	// 통계
	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("📊 DATASET SUMMARY")
	fmt.Println(strings.Repeat("═", 60))
	fmt.Printf("Sequence length:        %d\n", SeqLen)
	fmt.Printf("Context length:         %d\n", ContextLen)
	fmt.Printf("Vocab size:             %d\n", ds.vocabSize)
	fmt.Printf("Total corpus lines:     %d\n", lineCount)
	fmt.Printf("Total tokens:           %d\n", len(allTokens))
	fmt.Printf("Train sequences:        %d\n", len(trainSeqs))
	fmt.Printf("Val sequences:          %d\n", len(valSeqs))
	fmt.Printf("Total pairs:            %d\n", len(trainSeqs)+len(valSeqs))

	// 파일 크기
	if info, err := os.Stat("data/train.bin"); err == nil {
		fmt.Printf("Train file size:        %.1f MB\n", float64(info.Size())/(1024*1024))
	}
	if info, err := os.Stat("data/val.bin"); err == nil {
		fmt.Printf("Val file size:          %.1f MB\n", float64(info.Size())/(1024*1024))
	}

	fmt.Println("\n✅ Phase C Complete!")
	fmt.Println("\nNext: go run train/main.go")
}

