package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// QAPair (qa_generator.go 와 동일 구조)
type QAPair struct {
	Question string `json:"q"`
	Answer   string `json:"a"`
	Source   string `json:"src"`
}

func main() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Step 2: QA 쌍 → Corpus 변환 + 토큰화 데이터 재생성        ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 1. qa_pairs.jsonl 로드
	fmt.Println("[1/4] qa_pairs.jsonl 로드 중...")
	pairs, err := loadQAPairs("data/qa_pairs.jsonl")
	if err != nil {
		fmt.Printf("❌ 로드 실패: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("✅ %d개 QA 쌍 로드\n\n", len(pairs))

	// 2. QA → 대화형 텍스트 변환
	fmt.Println("[2/4] QA → 대화형 텍스트 변환 중...")
	qaText := qaToText(pairs)
	fmt.Printf("✅ %d줄 생성\n\n", strings.Count(qaText, "\n")+1)

	// 3. 기존 corpus.txt 에 QA 텍스트 추가
	fmt.Println("[3/4] corpus.txt 에 QA 데이터 병합 중...")
	if err := appendToCorpus("data/corpus.txt", qaText); err != nil {
		fmt.Printf("❌ 실패: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("✅ corpus.txt 업데이트 완료\n")

	// 4. qa_corpus.txt 별도 저장 (순수 QA 전용)
	fmt.Println("[4/4] qa_corpus.txt 별도 저장 중...")
	if err := os.WriteFile("data/qa_corpus.txt", []byte(qaText), 0644); err != nil {
		fmt.Printf("❌ 실패: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("✅ data/qa_corpus.txt 저장 완료\n")

	// 통계
	fmt.Println("── 통계 ──────────────────────────────────────────────────────")
	bySource := map[string]int{}
	for _, p := range pairs {
		src := p.Source
		if strings.Contains(src, "/") {
			parts := strings.Split(src, "/")
			for i, pt := range parts {
				if pt == "modules" || pt == "core" || pt == "projects" {
					if i+1 < len(parts) {
						src = parts[i+1]
						break
					}
				}
			}
		}
		bySource[src]++
	}
	top := topN(bySource, 8)
	fmt.Println("출처별 QA 분포 (상위 8):")
	for _, kv := range top {
		fmt.Printf("  %-40s %d개\n", kv[0], kv[1].(int))
	}

	// 샘플 QA 텍스트 출력
	fmt.Println("\n── 샘플 변환 결과 (처음 3개) ─────────────────────────────────")
	lines := strings.Split(qaText, "\n")
	count := 0
	for _, line := range lines {
		if line != "" {
			fmt.Println(" ", line)
			count++
			if count >= 6 {
				break
			}
		}
	}

	fmt.Println("\n✅ Step 2 완료!")
	fmt.Println("\n다음 단계:")
	fmt.Println("  go run data/tokenize.go   # vocab 재생성")
	fmt.Println("  go run data/dataset.go    # train/val.bin 재생성")
}

func loadQAPairs(path string) ([]QAPair, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var pairs []QAPair
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		var p QAPair
