}

// qaToText QA 쌍을 대화형 텍스트로 변환
// 형식: Q: ... \n A: ... \n\n
func qaToText(pairs []QAPair) string {
	var sb strings.Builder
	for _, p := range pairs {
		// 너무 짧거나 긴 쌍 스킵
		if len(p.Question) < 3 || len(p.Answer) < 3 {
			continue
		}
		if len(p.Question)+len(p.Answer) > 500 {
			// 긴 답변은 자르기
			if len(p.Answer) > 400 {
				p.Answer = p.Answer[:400] + "..."
			}
		}
		sb.WriteString("Q: ")
		sb.WriteString(p.Question)
		sb.WriteString("\nA: ")
		sb.WriteString(p.Answer)
		sb.WriteString("\n\n")
	}
	return sb.String()
}

