    // 타입 추론이 어려워 str/int 모두 지원 위해 void* trick 사용
    // 사용자는 fl_str_array_push / fl_int_array_push 직접 쓰도록 유도
    return `fl_str_array_push(&${arr}, ${val})`;
  }

  return '';
}

